"""Blueprint and component tools for UE5 MCP server.

Note on UE5.7 Python limitations:
- Blueprint SCS (SimpleConstructionScript) is NOT exposed to Python in UE5.7.
- Components can be added to LIVE ACTORS at runtime via new_object + k2_attach_to.
- Blueprint assets can be created, compiled, and spawned.
- Blueprint CDO default values can be read/set.
"""

from __future__ import annotations

import json
import logging

logger = logging.getLogger("ue5-mcp.tools.blueprints")

from ._validation import (
    sanitize_class_name, sanitize_label, sanitize_content_path,
    sanitize_property_name, escape_for_fstring, make_error,
)


def register(server, ue):
    @server.tool(
        name="ue_create_blueprint",
        description=(
            "Create a new Blueprint asset. Returns the asset path. "
            "parent_class can be 'Actor', 'Pawn', 'Character', 'PlayerController', etc."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def create_blueprint(
        name: str,
        folder: str = "/Game/Blueprints",
        parent_class: str = "Actor",
    ) -> str:
        """Create a new Blueprint class asset."""
        if err := sanitize_label(name, "name"):
            return make_error(err)
        if err := sanitize_content_path(folder, "folder"):
            return make_error(err)
        if err := sanitize_class_name(parent_class, "parent_class"):
            return make_error(err)

        safe_name = escape_for_fstring(name)
        safe_folder = escape_for_fstring(folder)
        safe_class = escape_for_fstring(parent_class)
        code = f"""
import unreal

asset_tools = unreal.AssetToolsHelpers.get_asset_tools()
factory = unreal.BlueprintFactory()
factory.set_editor_property("ParentClass", getattr(unreal, "{safe_class}", unreal.Actor))

blueprint = asset_tools.create_asset("{safe_name}", "{safe_folder}", None, factory)
if blueprint:
    unreal.EditorAssetLibrary.save_asset("{safe_folder}/{safe_name}")
    print("RESULT:" + blueprint.get_path_name())
else:
    print("RESULT:CREATE_FAILED")
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_add_component",
        description=(
            "Add a component to a LIVE ACTOR in the level (not a Blueprint asset). "
            "Provide the actor's object path. component_class can be "
            "'StaticMeshComponent', 'PointLightComponent', 'SpotLightComponent', "
            "'AudioComponent', 'BoxComponent', 'SphereComponent', "
            "'SkeletalMeshComponent', 'NiagaraComponent', 'DecalComponent', etc. "
            "Returns the list of all components on the actor after adding."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def add_component(
        actor_label: str,
        component_class: str,
        component_name: str | None = None,
    ) -> str:
        """Add a component to a live actor by label. Uses new_object + k2_attach_to."""
        if err := sanitize_label(actor_label, "actor_label"):
            return make_error(err)
        if err := sanitize_class_name(component_class, "component_class"):
            return make_error(err)
        if component_name is not None:
            if err := sanitize_label(component_name, "component_name"):
                return make_error(err)

        comp_name = component_name or component_class.replace("Component", "")
        safe_label = escape_for_fstring(actor_label)
        safe_cc = escape_for_fstring(component_class)
        safe_cn = escape_for_fstring(comp_name)
        code = f"""
import unreal, json

subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actors = subsystem.get_all_level_actors()
actor = None
for a in actors:
    if a.get_actor_label() == "{safe_label}":
        actor = a
        break

if actor is None:
    print("RESULT:" + json.dumps({{"error": "Actor not found: {safe_label}"}}))
else:
    comp_class = getattr(unreal, "{safe_cc}", None)
    if comp_class is None:
        print("RESULT:" + json.dumps({{"error": "Component class not found: {safe_cc}"}}))
    else:
        comp = unreal.new_object(comp_class, actor, "{safe_cn}")
        if comp and actor.root_component:
            comp.k2_attach_to(actor.root_component)

        comps = actor.get_components_by_class(unreal.ActorComponent)
        comp_list = [c.get_class().get_name() for c in comps]
        print("RESULT:" + json.dumps({{
            "actor": actor.get_actor_label(),
            "added": "{safe_cn}",
            "class": "{safe_cc}",
            "all_components": comp_list
        }}))
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_set_component_property",
        description=(
            "Set a property on a component of a live actor. "
            "Find the component by class name (e.g. 'StaticMeshComponent'). "
            "For asset references (meshes, materials), pass the content path as a string."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def set_component_property(
        actor_label: str,
        component_class: str,
        property_name: str,
        value: str,
    ) -> str:
        """Set a property on an actor's component. value is JSON (string, number, object, etc.)."""
        if err := sanitize_label(actor_label, "actor_label"):
            return make_error(err)
        if err := sanitize_class_name(component_class, "component_class"):
            return make_error(err)
        if err := sanitize_property_name(property_name):
            return make_error(err)
        # Validate value is parseable JSON
        try:
            json.loads(value)
        except json.JSONDecodeError as e:
            return make_error(f"Invalid JSON value: {e}")

        safe_label = escape_for_fstring(actor_label)
        safe_cc = escape_for_fstring(component_class)
        safe_prop = escape_for_fstring(property_name)
        safe_val = escape_for_fstring(value)
        code = f"""
import unreal, json

subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actors = subsystem.get_all_level_actors()
actor = None
for a in actors:
    if a.get_actor_label() == "{safe_label}":
        actor = a
        break

if actor is None:
    print("RESULT:" + json.dumps({{"error": "Actor not found: {safe_label}"}}))
else:
    comp_class = getattr(unreal, "{safe_cc}", None)
    comp = actor.get_component_by_class(comp_class) if comp_class else None

    if comp is None:
        comps = actor.get_components_by_class(unreal.ActorComponent)
        available = [c.get_class().get_name() for c in comps]
        print("RESULT:" + json.dumps({{"error": "Component not found: {safe_cc}", "available": available}}))
    else:
        val = json.loads('''{safe_val}''')
        # Handle asset path strings
        if isinstance(val, str) and val.startswith("/"):
            asset = unreal.EditorAssetLibrary.load_asset(val)
            if asset:
                val = asset
        try:
            comp.set_editor_property("{safe_prop}", val)
            print("RESULT:" + json.dumps({{"set": true, "component": "{safe_cc}", "property": "{safe_prop}"}}))
        except Exception as e:
            print("RESULT:" + json.dumps({{"error": str(e)}}))
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_set_blueprint_defaults",
        description=(
            "Set default property values on a Blueprint's Class Default Object (CDO). "
            "Properties are passed as a JSON object string, e.g. "
            "'{\"MaxHealth\": 100, \"Speed\": 600.0}'"
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def set_blueprint_defaults(
        blueprint_path: str,
        properties: str,
    ) -> str:
        """Set default values on a Blueprint's CDO. properties is a JSON string of key-value pairs."""
        if err := sanitize_content_path(blueprint_path, "blueprint_path"):
            return make_error(err)
        # Validate properties is valid JSON object
        try:
            props = json.loads(properties)
            if not isinstance(props, dict):
                return make_error("properties must be a JSON object")
            for key in props:
                if err := sanitize_property_name(key, f"property '{key}'"):
                    return make_error(err)
        except json.JSONDecodeError as e:
            return make_error(f"Invalid JSON in properties: {e}")

        safe_bp = escape_for_fstring(blueprint_path)
        safe_props = escape_for_fstring(properties)
        code = f"""
import unreal, json

bp = unreal.EditorAssetLibrary.load_asset("{safe_bp}")
if bp is None:
    print("RESULT:" + json.dumps({{"error": "Blueprint not found: {safe_bp}"}}))
else:
    cdo = unreal.get_default_object(bp.generated_class())
    props = json.loads('''{safe_props}''')
    results = {{}}
    for key, value in props.items():
        try:
            cdo.set_editor_property(key, value)
            results[key] = "set"
        except Exception as e:
            results[key] = str(e)

    unreal.BlueprintEditorLibrary.compile_blueprint(bp)
    unreal.EditorAssetLibrary.save_asset("{safe_bp}")
    print("RESULT:" + json.dumps({{"blueprint": "{safe_bp}", "properties": results}}))
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_compile_blueprint",
        description="Compile a Blueprint asset. Run this after making changes to ensure they take effect.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def compile_blueprint(blueprint_path: str) -> str:
        """Compile and save a Blueprint."""
        if err := sanitize_content_path(blueprint_path, "blueprint_path"):
            return make_error(err)

        safe_bp = escape_for_fstring(blueprint_path)
        code = f"""
import unreal, json

bp = unreal.EditorAssetLibrary.load_asset("{safe_bp}")
if bp is None:
    print("RESULT:" + json.dumps({{"error": "Blueprint not found: {safe_bp}"}}))
else:
    unreal.BlueprintEditorLibrary.compile_blueprint(bp)
    unreal.EditorAssetLibrary.save_asset("{safe_bp}")
    print("RESULT:" + json.dumps({{"blueprint": "{safe_bp}", "compiled": True}}))
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_get_actor_components",
        description="List all components on a live actor in the level, with their classes.",
        annotations={
            "readOnlyHint": True,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def get_actor_components(actor_label: str) -> str:
        """Inspect an actor's component hierarchy by actor label."""
        if err := sanitize_label(actor_label, "actor_label"):
            return make_error(err)

        safe_label = escape_for_fstring(actor_label)
        code = f"""
import unreal, json

subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actors = subsystem.get_all_level_actors()
actor = None
for a in actors:
    if a.get_actor_label() == "{safe_label}":
        actor = a
        break

if actor is None:
    print("RESULT:" + json.dumps({{"error": "Actor not found: {safe_label}"}}))
else:
    comps = actor.get_components_by_class(unreal.ActorComponent)
    comp_list = []
    for c in comps:
        comp_list.append({{
            "class": c.get_class().get_name(),
            "name": c.get_name(),
        }})
    print("RESULT:" + json.dumps({{
        "actor": actor.get_actor_label(),
        "actor_class": actor.get_class().get_name(),
        "components": comp_list,
    }}))
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_spawn_blueprint",
        description="Spawn an instance of a Blueprint actor in the level.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def spawn_blueprint(
        blueprint_path: str,
        x: float = 0.0,
        y: float = 0.0,
        z: float = 0.0,
        rx: float = 0.0,
        ry: float = 0.0,
        rz: float = 0.0,
        label: str | None = None,
    ) -> str:
        """Spawn a Blueprint actor instance in the level."""
        if err := sanitize_content_path(blueprint_path, "blueprint_path"):
            return make_error(err)
        if label is not None:
            if err := sanitize_label(label):
                return make_error(err)

        safe_bp = escape_for_fstring(blueprint_path)
        label_line = ""
        if label:
            safe_lbl = escape_for_fstring(label)
            label_line = f'\n    actor.set_actor_label("{safe_lbl}")'
        code = f"""
import unreal, json

bp_class = unreal.EditorAssetLibrary.load_blueprint_class("{safe_bp}")
if bp_class is None:
    print("RESULT:" + json.dumps({{"error": "Blueprint not found: {safe_bp}"}}))
else:
    subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
    actor = subsystem.spawn_actor_from_class(
        bp_class,
        unreal.Vector({x}, {y}, {z}),
        unreal.Rotator({rx}, {ry}, {rz})
    )
    if actor:{label_line}
        print("RESULT:" + actor.get_path_name())
    else:
        print("RESULT:" + json.dumps({{"error": "Spawn failed"}}))
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

"""Motion graphics tools for UE5 MCP server.

Convenience wrappers for Avalanche, ClonerEffector, Niagara, and PCG plugins.
All route through ue_execute_python under the hood.
"""

from __future__ import annotations

import json
import logging

logger = logging.getLogger("ue5-mcp.tools.mograph")

from ._validation import sanitize_label, sanitize_content_path, escape_for_fstring, make_error


def register(server, ue):
    @server.tool(
        name="ue_create_cloner",
        description=(
            "Create a ClonerEffector actor that instances a mesh in a layout pattern. "
            "Requires the ClonerEffector plugin to be enabled."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def create_cloner(
        layout: str = "Grid",
        mesh_path: str = "/Engine/BasicShapes/Cube",
        count_x: int = 5,
        count_y: int = 5,
        count_z: int = 1,
        spacing: float = 200.0,
        x: float = 0.0,
        y: float = 0.0,
        z: float = 0.0,
        label: str | None = None,
    ) -> str:
        """Create a ClonerEffector. layout can be: Grid, Circle, Line, Sphere, Honeycomb, Cylinder."""
        valid_layouts = {"Grid", "Circle", "Line", "Sphere", "Honeycomb", "Cylinder"}
        if layout not in valid_layouts:
            return make_error(f"Invalid layout '{layout}'. Must be one of: {', '.join(sorted(valid_layouts))}")
        if err := sanitize_content_path(mesh_path, "mesh_path"):
            return make_error(err)
        if label is not None:
            if err := sanitize_label(label):
                return make_error(err)

        label_str = escape_for_fstring(label or "ClaudeCloner")
        code = f"""
import unreal

subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)

# Spawn the Cloner actor
cloner_class = unreal.find_class("ClonerActor") or unreal.find_class("ACEClonerActor")
if cloner_class is None:
    # Try loading from the plugin module
    cloner_class = unreal.load_class(None, "/Script/ClonerEffector.ClonerActor")

if cloner_class:
    cloner = subsystem.spawn_actor_from_class(
        cloner_class,
        unreal.Vector({x}, {y}, {z}),
        unreal.Rotator(0, 0, 0)
    )
    if cloner:
        cloner.set_actor_label("{label_str}")
        print("RESULT:CREATED " + cloner.get_path_name())
    else:
        print("RESULT:SPAWN_FAILED")
else:
    print("RESULT:CLASS_NOT_FOUND - ClonerEffector plugin may not be loaded")
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_create_niagara_system",
        description=(
            "Spawn a Niagara particle system actor in the level. "
            "Can use a template system asset or create a default one."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def create_niagara_system(
        system_asset: str | None = None,
        x: float = 0.0,
        y: float = 0.0,
        z: float = 0.0,
        label: str | None = None,
    ) -> str:
        """Spawn a Niagara system. system_asset is an optional content path to a NiagaraSystem asset."""
        if system_asset is not None:
            if err := sanitize_content_path(system_asset, "system_asset"):
                return make_error(err)
        if label is not None:
            if err := sanitize_label(label):
                return make_error(err)

        label_str = escape_for_fstring(label or "ClaudeNiagara")
        asset_line = ""
        if system_asset:
            safe_asset = escape_for_fstring(system_asset)
            asset_line = f"""
    system = unreal.EditorAssetLibrary.load_asset("{safe_asset}")
    if system:
        comp = actor.get_component_by_class(unreal.NiagaraComponent)
        if comp:
            comp.set_asset(system)
"""
        code = f"""
import unreal

subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actor = subsystem.spawn_actor_from_class(
    unreal.NiagaraActor if hasattr(unreal, 'NiagaraActor') else unreal.load_class(None, "/Script/Niagara.NiagaraActor"),
    unreal.Vector({x}, {y}, {z}),
    unreal.Rotator(0, 0, 0)
)
if actor:
    actor.set_actor_label("{label_str}")
{asset_line}
    print("RESULT:CREATED " + actor.get_path_name())
else:
    print("RESULT:SPAWN_FAILED")
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_create_pcg_graph",
        description=(
            "Create a PCG (Procedural Content Generation) volume actor in the level. "
            "Requires the PCG plugin to be enabled."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def create_pcg_graph(
        x: float = 0.0,
        y: float = 0.0,
        z: float = 0.0,
        extent_x: float = 1000.0,
        extent_y: float = 1000.0,
        extent_z: float = 500.0,
        label: str | None = None,
    ) -> str:
        """Create a PCG volume. extent controls the bounds of the procedural generation area."""
        if label is not None:
            if err := sanitize_label(label):
                return make_error(err)

        label_str = escape_for_fstring(label or "ClaudePCG")
        code = f"""
import unreal

subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)

# Try to find the PCG volume class
pcg_class = None
for class_name in ["PCGVolume", "APCGVolume", "PCGComponent"]:
    pcg_class = unreal.find_class(class_name)
    if pcg_class:
        break

if pcg_class is None:
    pcg_class = unreal.load_class(None, "/Script/PCG.PCGVolume")

if pcg_class:
    actor = subsystem.spawn_actor_from_class(
        pcg_class,
        unreal.Vector({x}, {y}, {z}),
        unreal.Rotator(0, 0, 0)
    )
    if actor:
        actor.set_actor_label("{label_str}")
        actor.set_actor_scale3d(unreal.Vector({extent_x / 100}, {extent_y / 100}, {extent_z / 100}))
        print("RESULT:CREATED " + actor.get_path_name())
    else:
        print("RESULT:SPAWN_FAILED")
else:
    print("RESULT:CLASS_NOT_FOUND - PCG plugin may not be loaded")
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

"""Viewport perception tools for UE5 MCP server.

Consumes from the ViewportPerception C++ plugin's HTTP endpoint (port 30011).
Falls back to SceneCapture2D via ue_execute_python if the plugin is unavailable.

Tier 3I: Includes bridge state correlation — viewport frames are tagged with
the current game state (question, sync_status) for full situational awareness.
"""

from __future__ import annotations

import json
import logging
import os
import re
import time
from pathlib import Path

import httpx

logger = logging.getLogger("ue5-mcp.tools.perception")

PERCEPTION_URL = os.environ.get("UE_PERCEPTION_URL", "http://localhost:30011")
PERCEPTION_TIMEOUT = 5.0
BRIDGE_DIR = Path.home() / ".translators"


def _read_bridge_state() -> dict | None:
    """Read current bridge state from bridge_state.usda (non-blocking, best-effort)."""
    state_file = BRIDGE_DIR / "bridge_state.usda"
    heartbeat_file = BRIDGE_DIR / "heartbeat.json"

    result = {
        "bridge_connected": False,
        "sync_status": None,
        "message_type": None,
        "current_question": None,
        "question_index": None,
        "question_total": None,
        "heartbeat_alive": False,
    }

    # Read bridge state
    if state_file.exists():
        try:
            content = state_file.read_text(encoding="utf-8")
            result["bridge_connected"] = True

            sync_match = re.search(r'string sync_status = "([^"]*)"', content)
            type_match = re.search(r'string message_type = "([^"]*)"', content)
            qid_match = re.search(r'string question_id = "([^"]*)"', content)
            idx_match = re.search(r'int index = (\d+)', content)
            total_match = re.search(r'int total = (\d+)', content)
            text_match = re.search(r'string text = "([^"]*)"', content)

            result["sync_status"] = sync_match.group(1) if sync_match else None
            result["message_type"] = type_match.group(1) if type_match else None
            result["current_question"] = qid_match.group(1) if qid_match else None
            result["question_index"] = int(idx_match.group(1)) if idx_match else None
            result["question_total"] = int(total_match.group(1)) if total_match else None
            if text_match and text_match.group(1):
                result["question_text"] = text_match.group(1)[:100]  # Truncate for payload size
        except (OSError, PermissionError):
            pass

    # Check heartbeat
    if heartbeat_file.exists():
        try:
            age = time.time() - heartbeat_file.stat().st_mtime
            result["heartbeat_alive"] = age < 15
            result["heartbeat_age_s"] = round(age, 1)
        except OSError:
            pass

    return result


async def _perception_request(method: str, path: str, body: dict | None = None) -> dict | None:
    """Make an HTTP request to the perception endpoint. Returns None on connection failure."""
    try:
        async with httpx.AsyncClient(base_url=PERCEPTION_URL, timeout=PERCEPTION_TIMEOUT) as client:
            if method == "GET":
                r = await client.get(path)
            else:
                r = await client.put(path, json=body or {})
            r.raise_for_status()
            return r.json()
    except (httpx.ConnectError, httpx.TimeoutException, httpx.HTTPStatusError):
        return None


async def _fallback_capture(ue, width: int, height: int, format: str) -> dict:
    """Fallback: capture via SceneCapture2D + Python in the editor.

    This re-renders the scene (performance cost) but works without the C++ plugin.
    """
    code = f"""
import unreal, json, base64, os, tempfile

# Get viewport info
world = unreal.EditorLevelLibrary.get_editor_world()
subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actors = subsystem.get_all_level_actors()
level_name = world.get_name() if world else "Unknown"

# Get active viewport camera
ecs = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem)
loc, rot = unreal.Vector(), unreal.Rotator()
try:
    vp = unreal.EditorLevelLibrary
    loc = ecs.get_level_viewport_camera_info()[0] if hasattr(ecs, 'get_level_viewport_camera_info') else unreal.Vector()
    rot = ecs.get_level_viewport_camera_info()[1] if hasattr(ecs, 'get_level_viewport_camera_info') else unreal.Rotator()
except Exception:
    pass

# Selected actors
selected = []
sel = unreal.EditorUtilityLibrary.get_selected_assets() if hasattr(unreal, 'EditorUtilityLibrary') else []
try:
    sel_actors = unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_selected_level_actors()
    selected = [a.get_actor_label() for a in sel_actors]
except Exception:
    pass

# Capture via screenshot
tmp_dir = tempfile.gettempdir().replace("\\\\", "/")
out_path = tmp_dir + "/ue_perception_capture.{format}"

# Use high-res screenshot
success = False
try:
    unreal.AutomationLibrary.take_high_res_screenshot({width}, {height}, out_path)
    success = True
except Exception:
    pass

if not success:
    # Fallback: use viewport screenshot command
    try:
        cmd = f"HighResShot {width}x{height}"
        unreal.SystemLibrary.execute_console_command(world, cmd)
    except Exception:
        pass

# Read and encode the image if it exists
image_b64 = ""
if os.path.exists(out_path):
    with open(out_path, "rb") as f:
        image_b64 = base64.b64encode(f.read()).decode("ascii")
    os.remove(out_path)

result = {{
    "image": image_b64,
    "width": {width},
    "height": {height},
    "format": "{format}",
    "frame_number": 0,
    "timestamp": 0,
    "camera": {{
        "location": [loc.x, loc.y, loc.z] if hasattr(loc, 'x') else [0, 0, 0],
        "rotation": [rot.pitch, rot.yaw, rot.roll] if hasattr(rot, 'pitch') else [0, 0, 0],
        "fov": 90.0
    }},
    "viewport": {{
        "size": [{width}, {height}],
        "type": "LevelEditor"
    }},
    "selection": selected,
    "scene": {{
        "map": level_name,
        "actor_count": len(actors)
    }},
    "timing": {{
        "delta_time": 0,
        "fps": 0
    }},
    "fallback": True
}}
print("RESULT:" + json.dumps(result))
"""
    return await ue.execute_python(code)


def register(server, ue):

    @server.tool(
        name="ue_viewport_percept",
        description=(
            "Capture the UE5 editor viewport -- returns the rendered frame as an image "
            "plus camera, selection, and scene metadata. Gives the AI situated visual awareness."
        ),
        annotations={
            "readOnlyHint": True,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def viewport_percept(
        width: int = 1280,
        height: int = 720,
        format: str = "jpeg",
        include_image: bool = True,
    ) -> str:
        """Capture a single viewport perception packet with correlated game state."""

        # Try the C++ plugin endpoint first
        result = await _perception_request("GET", "/perception/frame")

        if result is None:
            # Plugin not available -- try single-shot endpoint
            result = await _perception_request("PUT", "/perception/single", {
                "width": width,
                "height": height,
                "format": format,
            })

        if result is None:
            # Fall back to Python-based capture
            fallback = await _fallback_capture(ue, width, height, format)
            if fallback.get("error"):
                return json.dumps({
                    "error": "Viewport perception unavailable",
                    "detail": fallback["error"],
                    "hint": "Ensure the ViewportPerception plugin is enabled, or that the editor is running.",
                }, indent=2)
            result = fallback.get("result", fallback)

        if not include_image and isinstance(result, dict):
            result.pop("image", None)

        # Correlate with bridge game state
        if isinstance(result, dict):
            bridge_state = _read_bridge_state()
            if bridge_state:
                result["game_state"] = bridge_state

        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_viewport_watch",
        description=(
            "Start or stop continuous viewport awareness at the specified rate. "
            "When active, the perception system captures frames continuously."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def viewport_watch(
        action: str = "start",
        fps: float = 5.0,
        width: int = 768,
        height: int = 432,
    ) -> str:
        """Start/stop continuous viewport perception."""

        if action == "start":
            result = await _perception_request("PUT", "/perception/start", {
                "fps": fps,
                "width": width,
                "height": height,
            })
            if result is None:
                return json.dumps({
                    "error": f"ViewportPerception plugin not reachable at {PERCEPTION_URL}",
                    "hint": "Continuous capture requires the C++ plugin. Use ue_viewport_percept for single-shot capture.",
                }, indent=2)
            return json.dumps(result, indent=2)

        elif action == "stop":
            result = await _perception_request("PUT", "/perception/stop")
            if result is None:
                return json.dumps({"status": "stopped", "note": "Plugin was not reachable"}, indent=2)
            return json.dumps(result, indent=2)

        return json.dumps({"error": f"Unknown action '{action}'. Use 'start' or 'stop'."}, indent=2)

    @server.tool(
        name="ue_viewport_config",
        description="Configure the viewport perception system (resolution, format, capture rate).",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def viewport_config(
        max_fps: float | None = None,
        width: int | None = None,
        height: int | None = None,
        format: str | None = None,
        quality: int | None = None,
    ) -> str:
        """Configure the perception system. Only provided fields are updated."""

        config = {}
        if max_fps is not None:
            config["max_fps"] = max_fps
        if width is not None:
            config["width"] = width
        if height is not None:
            config["height"] = height
        if format is not None:
            config["format"] = format
        if quality is not None:
            config["quality"] = quality

        if not config:
            # Query current status
            result = await _perception_request("GET", "/perception/status")
            if result is None:
                return json.dumps({"error": "ViewportPerception plugin not reachable"}, indent=2)
            return json.dumps(result, indent=2)

        result = await _perception_request("PUT", "/perception/config", config)
        if result is None:
            return json.dumps({
                "error": f"ViewportPerception plugin not reachable at {PERCEPTION_URL}",
                "hint": "Configuration requires the C++ plugin to be running.",
            }, indent=2)
        return json.dumps(result, indent=2)

"""Property access tools for UE5 MCP server."""

from __future__ import annotations

import json
import logging

logger = logging.getLogger("ue5-mcp.tools.properties")

from ._validation import sanitize_object_path, sanitize_property_name, make_error


def register(server, ue):
    @server.tool(
        name="ue_get_property",
        description="Read a property value from any UObject in the editor by object path and property name.",
        annotations={
            "readOnlyHint": True,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def get_property(object_path: str, property_name: str) -> str:
        """Get a property. object_path is the full path (e.g. /Game/Maps/MainLevel.MainLevel:PersistentLevel.Cube_1)."""
        if err := sanitize_object_path(object_path):
            return make_error(err)
        if err := sanitize_property_name(property_name):
            return make_error(err)

        result = await ue.get_property(object_path, property_name)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_set_property",
        description="Set a property value on any UObject in the editor.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def set_property(object_path: str, property_name: str, value: str) -> str:
        """Set a property. value is a JSON string that will be parsed (e.g. '{"X": 100, "Y": 0, "Z": 50}' for vectors)."""
        if err := sanitize_object_path(object_path):
            return make_error(err)
        if err := sanitize_property_name(property_name):
            return make_error(err)
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError as e:
            return make_error(f"Invalid JSON value: {e}")

        result = await ue.set_property(object_path, property_name, parsed)
        return json.dumps(result, indent=2)

